#!/bin/bash
# entrypoint.sh — proxknox-pxe container with --network host.
# Same role as the pxe-server VM of the KVM variant, but without a VM:
#   - IP 192.168.200.2/24 set on pxebr0 (removed on shutdown)
#   - NAT of the pxe-lab segment to the host's default interface
#     (iptables rules tagged "proxknox-pxe", removed on shutdown)
#   - dnsmasq: DHCP + TFTP + DNS on the pxebr0 interface only
#   - HTTP :8000 serving /srv/http (preseed + files, generated by the orchestrator)
#   - UDP syslog 10514 -> /srv/logs/di-syslog.log
# Everything runs in the foreground; SIGTERM -> cleanup (IP, iptables, services).
set -euo pipefail

PXE_IF="pxebr0"
PXE_IP="192.168.200.2"
PXE_NET="192.168.200.0/24"
TAG="proxknox-pxe"
HTTP_PORT=8000

UP_IF="$(ip -o route show default | awk '{print $5; exit}')"
[ -n "$UP_IF" ] || { echo "[entrypoint] no default route on the host" >&2; exit 1; }
[ -e "/sys/class/net/$PXE_IF" ] || {
    echo "[entrypoint] interface $PXE_IF missing (libvirt pxe-lab network inactive?)" >&2
    exit 1
}
[ "$(cat /proc/sys/net/ipv4/ip_forward)" = "1" ] || {
    echo "[entrypoint] ip_forward=0 on the host (libvirt normally enables it)" >&2
    exit 1
}

# --- PXE server IP on the bridge, if missing ---------------------------------
ADDED_IP=0
if ! ip -o -4 addr show dev "$PXE_IF" | grep -q "${PXE_IP}/"; then
    ip addr add "${PXE_IP}/24" dev "$PXE_IF"
    ADDED_IP=1
fi

# --- tagged NAT + FORWARD (inserted at the HEAD: the pxe-lab network is
#     isolated for libvirt, which installs its own REJECT rules in
#     LIBVIRT_FWO/FWI — first match wins) --------------------------------------
ipt() { iptables -w "$@"; }
cleanup() {
    ipt -t nat -D POSTROUTING -s "$PXE_NET" -o "$UP_IF" -m comment \
        --comment "$TAG" -j MASQUERADE 2>/dev/null || true
    ipt -D FORWARD -i "$PXE_IF" -o "$UP_IF" -m comment --comment "$TAG" -j ACCEPT 2>/dev/null || true
    ipt -D FORWARD -i "$UP_IF" -o "$PXE_IF" -m comment --comment "$TAG" \
        -m conntrack --ctstate RELATED,ESTABLISHED -j ACCEPT 2>/dev/null || true
    [ "$ADDED_IP" = 1 ] && ip addr del "${PXE_IP}/24" dev "$PXE_IF" 2>/dev/null || true
    kill "$DNSMASQ_PID" "$HTTP_PID" "$SYSLOG_PID" 2>/dev/null || true
    exit 0
}
trap cleanup TERM INT

ipt -t nat -C POSTROUTING -s "$PXE_NET" -o "$UP_IF" -m comment \
    --comment "$TAG" -j MASQUERADE 2>/dev/null || \
ipt -t nat -A POSTROUTING -s "$PXE_NET" -o "$UP_IF" -m comment \
    --comment "$TAG" -j MASQUERADE
ipt -C FORWARD -i "$PXE_IF" -o "$UP_IF" -m comment --comment "$TAG" -j ACCEPT 2>/dev/null || \
ipt -I FORWARD 1 -i "$PXE_IF" -o "$UP_IF" -m comment --comment "$TAG" -j ACCEPT
ipt -C FORWARD -i "$UP_IF" -o "$PXE_IF" -m comment --comment "$TAG" \
    -m conntrack --ctstate RELATED,ESTABLISHED -j ACCEPT 2>/dev/null || \
ipt -I FORWARD 1 -i "$UP_IF" -o "$PXE_IF" -m comment --comment "$TAG" \
    -m conntrack --ctstate RELATED,ESTABLISHED -j ACCEPT
echo "[entrypoint] NAT $PXE_NET -> $UP_IF (rules tagged $TAG, at the head of FORWARD)"

# --- TFTP tree: pxelinux from the Debian packages + kernel/initrd + config
PXELINUX0="$(ls /usr/lib/PXE*/pxelinux.0 /usr/lib/PXELINUX/pxelinux.0 2>/dev/null | head -1)"
LDLINUX="$(ls /usr/lib/syslinux/modules/bios/ldlinux.c32 2>/dev/null | head -1)"
[ -n "$PXELINUX0" ] && [ -n "$LDLINUX" ] || {
    echo "[entrypoint] pxelinux.0/ldlinux.c32 not found in the image" >&2; exit 1; }
cp -f "$PXELINUX0" /srv/tftp/pxelinux.0
cp -f "$LDLINUX"   /srv/tftp/ldlinux.c32
chmod 644 /srv/tftp/pxelinux.0 /srv/tftp/ldlinux.c32

# --- dnsmasq: DHCP/TFTP/DNS restricted to pxebr0 (host netns) -----------------
mkdir -p /srv/logs
chmod 0777 /srv/logs
cat > /srv/dnsmasq.conf <<EOF
# dnsmasq (proxknox-pxe container, host netns) — pxe-lab segment only
interface=${PXE_IF}
bind-dynamic
except-interface=lo
domain=pxe.lab
dhcp-authoritative
dhcp-range=192.168.200.100,192.168.200.200,255.255.255.0,12h
dhcp-option=option:router,${PXE_IP}
dhcp-option=option:dns-server,${PXE_IP}
dhcp-boot=pxelinux.0
enable-tftp
tftp-root=/srv/tftp
no-resolv
server=1.1.1.1
server=8.8.8.8
log-dhcp
log-queries
log-facility=/srv/logs/dnsmasq.log
dhcp-leasefile=/srv/logs/dnsmasq.leases
EOF
# Static MAC -> IP reservations (mounted volume, written by the chain: VMs
# with controlled MACs always get the same IP; e.g. E2E test VM).
# dnsmasq ignores a missing dhcp-host -> conditional inclusion.
[ -f /srv/logs/dnsmasq-dhcp-hosts.conf ] && \
    echo "conf-file=/srv/logs/dnsmasq-dhcp-hosts.conf" >> /srv/dnsmasq.conf

dnsmasq --conf-file=/srv/dnsmasq.conf --no-daemon --user=root \
    > /srv/logs/dnsmasq-stderr.log 2>&1 &
DNSMASQ_PID=$!

python3 -m http.server "$HTTP_PORT" --directory /srv/http \
    > /srv/logs/http.log 2>&1 &
HTTP_PID=$!

python3 /usr/local/bin/syslog-listener.py /srv/logs/di-syslog.log &
SYSLOG_PID=$!

echo "[entrypoint] services ready: DHCP/DNS/TFTP (53/67/69 on $PXE_IF), "
echo "[entrypoint]              HTTP :$HTTP_PORT, syslog UDP 10514"

wait -n
cleanup
